from pathlib import Path
from html import escape
stages=[
('14 days before','December 18, 2026','Your next Antarctica installment is coming up','A little planning now, a big adventure ahead. Your next installment is due in two weeks.','Please arrange your Bitcoin payment by January 1, 2027 to keep your expedition booking on track.'),
('4 days before','December 28, 2026','Four days until your Antarctica payment is due','Your next installment is due in four days.','Open your booking to review the amount and payment instructions. Allow time for your Bitcoin payment to be confirmed.'),
('Due today','January 1, 2027','Your Antarctica installment is due today','Today is the due date for your next installment.','Please open your booking and complete your Bitcoin payment today. If you need help, contact us at inbox@btcpp.dev.'),
('Overdue · every other day','January 3, 2027','Your Antarctica installment is 2 days overdue','We haven’t recorded your installment payment yet.','Please complete payment to keep your reservation. If it remains unpaid for 30 days after the due date, your reservation will be cancelled, your berths released, and all payments already made will be retained. For this installment, that date is January 31, 2027.'),
('Final reminder · day 28','January 29, 2027','Action needed: two days to keep your Antarctica reservation','Your installment is 28 days overdue.','If payment remains outstanding on January 31, 2027, your reservation will be cancelled, your berths released, and all payments already made will be retained. Please pay now or contact inbox@btcpp.dev if you have already paid or need help.'),
('Cancellation · day 30','January 31, 2027','Your Antarctica reservation has been cancelled','Your installment remained unpaid for 30 days after its due date.','Your reservation has been cancelled, your berths released, and all payments already made have been retained under the booking terms. Contact inbox@btcpp.dev with any questions.')]
parts=[]
for i,(label,date,subject,intro,body) in enumerate(stages):
 parts.append(f'''<section id="stage-{i}" class="stage" {'hidden' if i else ''}><p class="subject"><b>Subject:</b> {escape(subject)}<br><b>Example send date:</b> {date}</p><article class="email"><header><span class="brand">bitcoin<span>++</span></span><p>COLD STORAGE EDITION</p></header><img src="http://127.0.0.1:8110/static/img/antarctica/leading.png" alt="Antarctica expedition illustration"><main><h1>{escape(subject)}</h1><p>{escape(intro)}</p><div class="details"><b>Installment 2 of 5 · $3,340 USD</b><br>Due January 1, 2027<br>January 24–February 5, 2028 expedition<br>Sample booking · 1 passenger · two-person cabin</div><p>{escape(body)}</p><p>If an installment remains unpaid for 30 days after its due date, the reservation will be cancelled, berths released, and all payments already made retained.</p><a class="button" href="http://127.0.0.1:8110/?booking=1">View your booking {'and pay' if i<5 else 'details'} →</a><p>Questions or a payment that hasn’t appeared? Email <a href="mailto:inbox@btcpp.dev">inbox@btcpp.dev</a>.</p><p class="fine">This is a booking update, separate from newsletters.</p></main></article></section>''')
parts.append('<section id="stage-6" class="stage" hidden><p class="subject"><b>To:</b> inbox@btcpp.dev<br><b>Subject:</b> Antarctica booking automatically cancelled · SAMPLE-BOOKING</p><article class="email"><main><h1>Reservation cancelled after 30 days overdue.</h1><p>Internal notification — sample data only.</p><div class="details"><b>Booking:</b> SAMPLE-BOOKING<br><b>Purchaser:</b> Sample Guest · guest@example.test<br><b>Expedition:</b> January 24–February 5, 2028<br><b>Cancellation date:</b> January 31, 2027 (example; operational cutoff timezone pending)<br><b>Reason:</b> Installment 2 remained unpaid for 30 days</div><ul><li>Overdue installment: $3,340 USD, due January 1, 2027</li><li>Payments retained: $3,340 USD passage payment; actual Bitcoin amounts and any tax to be itemized from payment records</li><li>Berths released: 1 spot in a two-person cabin</li><li>Passenger cancellation notice: queued (sample state)</li></ul><p><a class="button" href="http://127.0.0.1:8110/?booking=1">View sample booking →</a></p><p class="fine">The production notification must link to a staff-authorized booking record and include the cancellation event reference, accepted policy version, payment references, and actual customer-notice delivery status.</p></main></article></section>')
stages.append(('Internal cancellation notice', '', '', '', ''))
nav=''.join(f'<button type="button" data-stage="{i}" aria-pressed="{str(i==0).lower()}">{escape(s[0])}</button>' for i,s in enumerate(stages))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Antarctica installment email previews</title><style>
@font-face{font-family:UbuntuBrand;src:url('http://127.0.0.1:8110/static/fonts/Ubuntu-BoldItalic.ttf');font-weight:700;font-style:italic}*{box-sizing:border-box}body{margin:0;background:#edf3f5;color:#063747;font:16px/1.6 Arial,sans-serif}.notice{padding:16px 24px;background:#063747;color:white;text-align:center}nav{display:flex;flex-wrap:wrap;gap:8px;max-width:1000px;margin:20px auto;padding:0 20px}button{padding:10px 14px;background:white;border:1px solid #93b6c1;cursor:pointer;color:#063747}button[aria-pressed=true]{background:#eb7549}.stage{max-width:640px;margin:0 auto 40px}.subject{padding:0 20px}.email{background:white}.email header{padding:24px 28px}.brand{font:italic 700 27px UbuntuBrand,Ubuntu,Arial,sans-serif}.brand span{letter-spacing:-.19em;margin-right:.19em}.email header p{font-size:11px;letter-spacing:2px;margin:0}.email img{width:100%;height:190px;object-fit:cover;object-position:center 55%;display:block}main{padding:28px}h1{font:36px/1.15 Georgia,serif}.details{padding:18px;background:#eaf3f5}.button{display:inline-block;background:#eb7549;padding:12px 20px;text-decoration:none;color:#063747;font-weight:bold}a{color:#ad4123}.fine{font-size:12px;color:#426674}</style><div class="notice"><b>Draft email previews · sample data · nothing will be sent</b><br>Reminder scheduling and automatic cancellation are not implemented. The cancellation time zone still needs to be finalized.</div><nav aria-label="Email stages">'''+nav+'</nav>'+''.join(parts)+'''<script>document.querySelectorAll('[data-stage]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.stage').forEach(s=>s.hidden=s.id!=='stage-'+button.dataset.stage);document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));</script></html>'''
Path('outputs/antarctica-reminder-preview/index.html').write_text(html)
